func (r *smimeConfigResource) identityOf(m smimeConfigModel) string {
	if v := m.Identity.ValueString(); v != "" {
		return v
	}
	if v := m.ID.ValueString(); v != "" {
		return v
	}
	return ""
}

func (r *smimeConfigResource) refresh(ctx context.Context, identity string, m *smimeConfigModel, diags *diag.Diagnostics, reflected func(map[string]any) bool) bool {
	get := func(ctx context.Context) (map[string]any, bool, error) {
		res, gerr := r.client.EXO.GetSmimeConfig(ctx, exo.GetSmimeConfigParams{Identity: identity})
		if gerr != nil {
			if isNotFound(gerr) {
				return nil, false, nil
			}
			return nil, false, gerr
		}
		o := firstObject(res.Value)
		return o, o != nil, nil
	}
	obj, present, err := resourcex.LoadUntil(ctx, consistency.Config{}, get, reflected)
	if err != nil {
		diags.AddError("Get-SmimeConfig failed", err.Error())
		return false
	}
	if !present {
		return false
	}
	readSmimeConfig(ctx, obj, m)
	return true
}

func readSmimeConfig(ctx context.Context, obj map[string]any, m *smimeConfigModel) {
	m.ID = types.StringValue(firstNonEmptyStr(getString(obj, "Guid"), getString(obj, "Id"), getString(obj, "Identity")))
	m.NoSignOnReply = types.BoolValue(getBool(obj, "NoSignOnReply"))
	m.OWAAllowUserChoiceOfSigningCertificate = types.BoolValue(getBool(obj, "OWAAllowUserChoiceOfSigningCertificate"))
	m.OWAAlwaysEncrypt = types.BoolValue(getBool(obj, "OWAAlwaysEncrypt"))
	m.OWAAlwaysSign = types.BoolValue(getBool(obj, "OWAAlwaysSign"))
	m.OWABCCEncryptedEmailForking = types.Int64Value(getInt(obj, "OWABCCEncryptedEmailForking"))
	m.OWACRLConnectionTimeout = types.Int64Value(getInt(obj, "OWACRLConnectionTimeout"))
	m.OWACRLRetrievalTimeout = types.Int64Value(getInt(obj, "OWACRLRetrievalTimeout"))
	m.OWACheckCRLOnSend = types.BoolValue(getBool(obj, "OWACheckCRLOnSend"))
	m.OWAClearSign = types.BoolValue(getBool(obj, "OWAClearSign"))
	m.OWACopyRecipientHeaders = types.BoolValue(getBool(obj, "OWACopyRecipientHeaders"))
	m.OWADLExpansionTimeout = types.Int64Value(getInt(obj, "OWADLExpansionTimeout"))
	m.OWADisableCRLCheck = types.BoolValue(getBool(obj, "OWADisableCRLCheck"))
	m.OWAEncryptTemporaryBuffers = types.BoolValue(getBool(obj, "OWAEncryptTemporaryBuffers"))
	m.OWAEncryptionAlgorithms = types.StringValue(getString(obj, "OWAEncryptionAlgorithms"))
	m.OWAForceSMIMEClientUpgrade = types.BoolValue(getBool(obj, "OWAForceSMIMEClientUpgrade"))
	m.OWAIncludeCertificateChainAndRootCertificate = types.BoolValue(getBool(obj, "OWAIncludeCertificateChainAndRootCertificate"))
	m.OWAIncludeCertificateChainWithoutRootCertificate = types.BoolValue(getBool(obj, "OWAIncludeCertificateChainWithoutRootCertificate"))
	m.OWAIncludeSMIMECapabilitiesInMessage = types.BoolValue(getBool(obj, "OWAIncludeSMIMECapabilitiesInMessage"))
	m.OWAOnlyUseSmartCard = types.BoolValue(getBool(obj, "OWAOnlyUseSmartCard"))
	m.OWASenderCertificateAttributesToDisplay = types.StringValue(getString(obj, "OWASenderCertificateAttributesToDisplay"))
	m.OWASignedEmailCertificateInclusion = types.BoolValue(getBool(obj, "OWASignedEmailCertificateInclusion"))
	m.OWASigningAlgorithms = types.StringValue(getString(obj, "OWASigningAlgorithms"))
	m.OWATripleWrapSignedEncryptedMail = types.BoolValue(getBool(obj, "OWATripleWrapSignedEncryptedMail"))
	m.OWAUseKeyIdentifier = types.BoolValue(getBool(obj, "OWAUseKeyIdentifier"))
	m.OWAUseSecondaryProxiesWhenFindingCertificates = types.BoolValue(getBool(obj, "OWAUseSecondaryProxiesWhenFindingCertificates"))
	m.SMIMECertificateIssuingCA = types.StringValue(getObjectJSON(obj, "SMIMECertificateIssuingCA"))
	_ = ctx
}

